// TH14 v1.00b st03.ecl.txt::MainSub04 (midboss early-kill reward wave)
// Entry :639-654; async right half :656-671; Phantom02 :917-940; Phantom02_at :942-971.
const TIME_LIMIT: int = 3524;
const OPENING_BUFFER: int = 120;

// Source etSprite(0,5,6): TH14 native type5 BALL2 -> modern slot 432, color 6.
const TH14_BALL2: int = 432;

async sub phantom02_at() {
    // :953-961 difficulty push popped by wait([-1]) at :962.
    var delay: int = 60;
    if global(GVAR_RANK) == RANK_EASY {
        delay = 60 + rand(180);          // Easy: 60 + (RAND % 180)
    }
    wait(delay);
    // :963 diffI(A,1,3,5,6) shot count per rank.
    var shots: int = 6;
    if global(GVAR_RANK) == RANK_EASY {
        shots = 1;
    } else if global(GVAR_RANK) == RANK_NORMAL {
        shots = 3;
    } else if global(GVAR_RANK) == RANK_HARD {
        shots = 5;
    }
    // :964-969 loop fires then waits 60.
    for i in 0..shots {
        // etAim(0,0) 1-way aimed: aim from the muzzle at fire time.
        var a: angle = atan2($player_y - $self_y, $player_x - $self_x);
        // :952 ANIM type2 a=1 birth retro displacement 4*velocity = 6px back along the shot.
        _ = fire(TH14_BALL2, 6,
                 $self_x - 6fx * cos(a), $self_y - 6fx * sin(a),
                 1.5fx, a, none, none);
        wait(60);
    }
}

async sub phantom02(dir: int) {
    // :921-922 boxes (28/28 and 16/16 -> radii 14/8); :926 async emitter.
    // :930-932 setDeath(Phantom02_at2) only exists on N/H/L but is unreachable here (see report).
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    spawn phantom02_at();
    // :928 moveCircleRel(RANDRAD, 1deg/frame, 0, 0); REL centre is the zero REL layer.
    var phase: angle = (rand(65536) - 32768) as angle;
    var k: int = 0;
    loop {
        // :927 moveVel(0,1) ABS drift plus :929 radius 0->16 over 80 ticks.
        // Frame k shows P(k); pre-arrange P(k+1)-P(k) for this frame's integration.
        var rk: fx = 16fx;
        if k < 80 {
            rk = (16 * k) as fx / 80;
        }
        var kn: int = k + 1;
        var rn: fx = 16fx;
        if kn < 80 {
            rn = (16 * kn) as fx / 80;
        }
        var ph0: angle = phase;
        var ph1: angle = phase + 1deg;
        var dx: fx = rn * cos(ph1) - rk * cos(ph0);
        var dy: fx = rn * sin(ph1) - rk * sin(ph0);
        var vx: fx = 1fx + dx;
        // enmCreateMF initial mirror=1: source reflects x/angle at each movement write.
        if dir < 0 {
            vx = -vx;
        }
        move_vel_xy(0, vx, dy, EASE_LINEAR);
        phase = ph1;
        k = kn;
        wait(1);
    }
}

async sub spawn_left() {
    // :643-652 28 spawns, 60-frame interval, y = 32 + RANDF*128.
    for i in 0..28 {
        var y: fx = 32fx + ((rand(65536) - 32768) as fx / 65536 + 0.5fx) * 128fx;
        _ = spawn_enemy(-192fx, y, 180, 0, 1000, 0, phantom02(1));
        wait(60);
    }
}

async sub spawn_right() {
    // :656-671 same 28 spawns after the 30-frame async delay; enmCreateMF.
    wait(30);
    for i in 0..28 {
        var y: fx = 32fx + ((rand(65536) - 32768) as fx / 65536 + 0.5fx) * 128fx;
        _ = spawn_enemy(192fx, y, 180, 0, 1000, 0, phantom02(-1));
        wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn spawn_left();
    spawn spawn_right();
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
